changeSet.sql:
alter table KB_USAGE_STAT add column if not exists billable_users bigint;
alter table KB_USAGE_STAT add column if not exists billable_sites bigint;
alter table KB_USAGE_STAT add column if not exists units bigint;

update KB_USAGE_STAT set billable_users = 0 where billable_users is null;
alter table KB_USAGE_STAT alter column billable_users set not null;
alter table KB_USAGE_STAT alter column billable_users set default 0;

update KB_USAGE_STAT set billable_sites = 0 where billable_sites is null;
alter table KB_USAGE_STAT alter column billable_sites set not null;
alter table KB_USAGE_STAT alter column billable_sites set default 0;

update KB_USAGE_STAT set units = 0 where units is null;
alter table KB_USAGE_STAT alter column units set not null;
alter table KB_USAGE_STAT alter column units set default 0;

alter table KB_USAGE_STAT alter column  hard_disk_usage set default 0;
alter table KB_USAGE_STAT alter column  users set default 0;
alter table KB_USAGE_STAT alter column  contents set default 0;
alter table KB_USAGE_STAT alter column  resources set default 0;

update KB_USAGE_STAT set hard_disk_usage = 0 where hard_disk_usage is null;
update KB_USAGE_STAT set users = 0 where users is null;
update KB_USAGE_STAT set contents = 0 where contents is null;
update KB_USAGE_STAT set resources = 0 where  resources is null;

create table rs_user_pivot
(
    user_id bigint primary key,
    pivot_last_update timestamp with time zone,
    data jsonb
);
CREATE INDEX idx_rs_user_pivot_clf ON rs_user_pivot USING GIN((data->'personMember'->'classifiers') );
